WITH parsed AS (SELECT id, plan, effective_from, currency, tier_limits, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, AGGREGATE(tier_prices, CAST(0 AS DOUBLE), (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers) SELECT id, plan, effective_from, currency, avg_tier_price, NTILE(5) OVER (PARTITION BY currency ORDER BY entry_price, id) entry_price_bucket, ROW_NUMBER() OVER (ORDER BY avg_tier_price DESC, id) seq_no, NTILE(4) OVER (ORDER BY avg_tier_price, id) avg_tier_price_bucket, SUM(avg_tier_price) OVER (ORDER BY effective_from, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_avg_tier_price, LAG(entry_price, 1) OVER (ORDER BY avg_tier_price, id) prev_entry_price FROM parsed;
